"""Interactive play screen with pause/resume and immediate feedback."""

import tkinter as tk

from ..game.engine import GameState
from .screens import BaseScreen


class PlayScreen(BaseScreen):
    def __init__(self, app):
        super().__init__(app)
        self.game = app.game
        self.option_buttons = []
        self.feedback_var = tk.StringVar(value="")

        header = tk.Frame(self, bg="#0b1026")
        header.pack(fill="x", padx=16, pady=12)
        self.score_label = tk.Label(header, text="", bg="#0b1026", fg="white", font=("Helvetica", 14))
        self.score_label.pack(side="left")
        self.pause_btn = tk.Button(header, text="Pause", command=self._toggle_pause)
        self.pause_btn.pack(side="right")

        self.paused_label = tk.Label(self, text="", bg="#0b1026", fg="#ffb74d", font=("Helvetica", 16, "bold"))
        self.paused_label.pack(pady=6)

        self.question_label = tk.Label(self, text="", bg="#0b1026", fg="white", wraplength=720, justify="center", font=("Helvetica", 18))
        self.question_label.pack(pady=20)

        self.options_frame = tk.Frame(self, bg="#0b1026")
        self.options_frame.pack(pady=10)

        self.feedback_label = tk.Label(self, textvariable=self.feedback_var, bg="#0b1026", fg="#8bc34a", font=("Helvetica", 14))
        self.feedback_label.pack(pady=10)

        self.next_btn = tk.Button(self, text="Next question", width=20, command=self._advance)
        self._render_question()

    def _update_header(self):
        self.score_label.config(text=f"Score: {self.game.score} / {self.game.total_questions}")
        self.pause_btn.config(text="Resume" if self.game.state == GameState.PAUSED else "Pause")
        self.paused_label.config(text="Game paused — press Resume to continue" if self.game.state == GameState.PAUSED else "")

    def _clear_options(self):
        for button in self.option_buttons:
            button.destroy()
        self.option_buttons.clear()

    def _render_question(self):
        question = self.game.current_question()
        if question is None:
            self.app.show_ending()
            return
        self._clear_options()
        self.feedback_var.set("")
        self.next_btn.pack_forget()
        self.question_label.config(text=question.prompt)
        for option in question.options:
            button = tk.Button(self.options_frame, text=option, width=22, command=lambda value=option: self._answer(value))
            button.pack(pady=4)
            self.option_buttons.append(button)
        self._update_header()

    def _answer(self, option):
        if self.game.state != GameState.PLAYING:
            return
        result = self.game.submit_answer(option)
        for button in self.option_buttons:
            button.config(state="disabled")
        if result.is_correct:
            self.feedback_var.set("Correct! Well done.")
        else:
            self.feedback_var.set(f"Not quite. The correct answer was: {result.correct_answer}")
        self.next_btn.config(text="See results" if result.finished else "Next question")
        self.next_btn.pack(pady=6)
        self._update_header()

    def _advance(self):
        if self.game.state == GameState.PAUSED:
            return
        if self.game.is_finished():
            self.app.show_ending()
        else:
            self._render_question()

    def _toggle_pause(self):
        if self.game.state == GameState.PLAYING:
            self.game.pause()
        elif self.game.state == GameState.PAUSED:
            self.game.resume()
        self._update_header()
